import { useState, useEffect } from "react";
import { createPortal } from "react-dom";

import { X, Check, Plus } from "lucide-react";
import { PremiumSelect } from "../ui/PremiumSelect";
import { cn } from "@/lib/utils";

import { useTranslation } from "react-i18next";
import type { Transaction } from "@/types";
import { useAccounts, useCategories, useCreateCategory } from "@/hooks/use-api";

interface AddTransactionModalProps {
    isOpen: boolean;
    onClose: () => void;
    onAdd: (transaction: Omit<Transaction, "id" | "created_at"> & { account_id: number }) => void;
    initialData?: Partial<Transaction>;
}

export function AddTransactionModal({ isOpen, onClose, onAdd, initialData }: AddTransactionModalProps) {
    const { t } = useTranslation();
    const { data: accounts } = useAccounts();
    const { data: categories } = useCategories();

    const [formData, setFormData] = useState({
        amount: "",
        description: "",
        type: "expense" as "income" | "expense",
        account_id: accounts?.[0]?.id || 0,
        category_id: 0
    });

    const [isAddingCategory, setIsAddingCategory] = useState(false);
    const [newCategoryName, setNewCategoryName] = useState("");
    const createCategory = useCreateCategory();

    // Reset or populate form when modal opens or initialData changes
    useEffect(() => {
        if (isOpen) {
            if (initialData) {
                setFormData({
                    amount: initialData.amount?.toString() || "",
                    description: initialData.description || "",
                    type: (initialData.type as "income" | "expense") || "expense",
                    account_id: initialData.account_id || accounts?.[0]?.id || 0,
                    category_id: initialData.category_id || 0
                });
            } else {
                setFormData({
                    amount: "",
                    description: "",
                    type: "expense",
                    account_id: accounts?.[0]?.id || 0,
                    category_id: 0
                });
            }
        }
    }, [isOpen, initialData, accounts]);

    const handleCreateCategory = () => {
        if (!newCategoryName.trim()) return;

        // Simple mapping for common category names to Lucide icons
        const iconMap: { [key: string]: string } = {
            'food': 'Utensils',
            'restaurant': 'Utensils',
            'groceries': 'ShoppingBag',
            'shopping': 'ShoppingPalette',
            'transport': 'Car',
            'rent': 'Home',
            'salary': 'Banknote',
            'gift': 'Gift',
            'health': 'Stethoscope'
        };

        const defaultIcon = iconMap[newCategoryName.toLowerCase().trim()] || (formData.type === 'income' ? 'TrendingUp' : 'TrendingDown');

        createCategory.mutate({
            name: newCategoryName,
            type: formData.type,
            icon: defaultIcon,
            color: "#3b82f6", // Default color
            user_id: 0 // handled by backend
        }, {
            onSuccess: (data) => {
                setFormData(prev => ({ ...prev, category_id: data.id }));
                setIsAddingCategory(false);
                setNewCategoryName("");
            }
        });
    };

    // Get currency symbol from selected account or default to $
    const selectedAccount = accounts?.find(a => a.id === (formData.account_id || accounts?.[0]?.id));
    const currencySymbol = selectedAccount
        ? new Intl.NumberFormat('en-US', { style: 'currency', currency: selectedAccount.currency }).formatToParts(0).find(part => part.type === 'currency')?.value || '$'
        : '$';

    // Filter categories by type
    const filteredCategories = categories?.filter(c => c.type === formData.type) || [];

    // Block background scroll when modal is open
    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = '';
        }
        return () => {
            document.body.style.overflow = '';
        };
    }, [isOpen]);

    // Update default account when accounts are loaded (only if not using initialData)
    useEffect(() => {
        if (!initialData && accounts && accounts.length > 0 && formData.account_id === 0) {
            setFormData(prev => ({ ...prev, account_id: accounts[0].id }));
        }
    }, [accounts, formData.account_id, initialData]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onAdd({
            description: formData.description,
            type: formData.type,
            amount: formData.amount ? parseFloat(formData.amount) : 0,
            account_id: Number(formData.account_id),
            category_id: formData.category_id > 0 ? Number(formData.category_id) : undefined
        });
        // We don't reset here immediately because the modal might be closing,
        // and the useEffect will handle reset on next open.
        onClose();
    };

    return createPortal(
        isOpen ? (
            <>
                {/* Backdrop */}
                <div
                    onClick={onClose}
                    className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999]"
