                    className="w-12 h-12 bg-primary text-primary-foreground flex items-center justify-center rounded-2xl shadow-xl shadow-primary/20 hover:opacity-90 transition-all"
                >
                    <Plus size={24} strokeWidth={3} />
                </button>
            </div>

            {/* List */}
            <div className="space-y-4">
                {isLoading ? (
                    <div className="flex justify-center py-12">
                        <div className="animate-spin">
                            <Repeat className="text-muted-foreground opacity-20" size={40} />
                        </div>
                    </div>
                ) : recurring.length === 0 ? (
                    <div className="bg-card/50 border border-dashed border-border rounded-[2.5rem] p-12 text-center space-y-4">
                        <div className="w-16 h-16 bg-muted rounded-2xl flex items-center justify-center mx-auto text-muted-foreground/30">
                            <Repeat size={32} />
                        </div>
                        <div className="space-y-1">
                            <h3 className="font-bold text-lg">{t('recurring.empty_title') || "No recurring transactions"}</h3>
                            <p className="text-muted-foreground text-sm max-w-[200px] mx-auto">
                                {t('recurring.empty_desc') || "Add your first one to start automating"}
                            </p>
                        </div>
                    </div>
                ) : (
                    <div className="grid gap-4">
                        {recurring.map((item) => (
                            <div
                                key={item.id}
                                className="relative group bg-card hover:bg-muted/30 border border-border/50 rounded-[2rem] p-6 flex flex-col items-center text-center gap-3"
                            >
                                <div className={cn(
                                    "w-16 h-16 rounded-[1.4rem] flex items-center justify-center text-white shadow-lg relative overflow-hidden shrink-0 border border-black/10 dark:border-white/10",
                                    item.category?.color || "bg-primary"
                                )}>
                                    <div className="absolute inset-0 bg-gradient-to-tr from-white/0 via-white/10 to-white/30" />
                                    <div className="absolute inset-0 bg-black/15 dark:bg-transparent" />
                                    <Repeat size={28} strokeWidth={3} className="relative z-10 drop-shadow-sm" />
                                </div>

                                <div className="flex-1 min-w-0">
                                    <h4 className="font-extrabold tracking-tight text-[18px] leading-tight text-foreground/90">{item.description}</h4>
                                    <div className="flex items-center justify-center gap-3 mt-1">
                                        <span className="flex items-center gap-1 text-[11px] font-black uppercase tracking-widest text-muted-foreground/60">
                                            <Calendar size={11} strokeWidth={2.5} />
                                            {item.interval}
                                        </span>
                                        <span className="flex items-center gap-1 text-[11px] font-black uppercase tracking-widest text-muted-foreground/60">
                                            <Wallet size={11} strokeWidth={2.5} />
                                            {item.account?.name}
                                        </span>
                                    </div>
                                </div>

                                <div className="flex flex-col items-center gap-1.5 shrink-0">
                                    <span className={cn(
                                        "font-black tracking-tighter text-[22px] leading-none flex items-center gap-1.5",
                                        item.type === 'income' ? "text-emerald-500" : "text-foreground"
                                    )}>
                                        {new Intl.NumberFormat(i18n.language, {
                                            style: "currency",
                                            currency: item.account?.currency || "USD"
                                        }).format(item.amount)}
                                        {item.type === 'income' ? ' +' : ' -'}
                                    </span>
                                    <span className="text-[11px] uppercase tracking-widest font-black text-muted-foreground/50">
                                        Next: {format(new Date(item.next_run_date), "dd MMM", { locale: dateLocale })}
                                    </span>
                                </div>

                                <button
                                    onClick={() => handleDelete(item.id)}
                                    className="opacity-0 group-hover:opacity-100 p-2 text-red-500 hover:bg-red-500/10 rounded-xl transition-all absolute top-4 right-4"
                                >
                                    <Trash2 size={18} />
                                </button>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <AddRecurringModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
            />
        </div>
    );
}

import { useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { ArrowLeft, Calendar, Wallet, Tag, TrendingUp, TrendingDown, RefreshCcw } from "lucide-react";
import { useTransaction, useAccounts, useCategories, useCreateTransaction } from "@/hooks/use-api";
import { useAuthStore } from "@/store/auth-store";
import type { Transaction } from "@/types";
import { AddTransactionModal } from "@/components/transactions/AddTransactionModal";

import { cn } from "@/lib/utils";
import api from "@/lib/axios"; // Or use a delete hook if you make one

export default function TransactionDetails() {
    const { id } = useParams();
    const navigate = useNavigate();
    const { t, i18n } = useTranslation();
    const user = useAuthStore((state) => state.user);
    const [isRedoModalOpen, setIsRedoModalOpen] = useState(false);
    const { mutate: createTransaction } = useCreateTransaction();

    // Convert id to number safely
    const transactionId = Number(id);
    const { data: transaction, isLoading, isError } = useTransaction(transactionId);
    const { data: accounts } = useAccounts();
    const { data: categories } = useCategories();

    // Helper to format currency
    const formatCurrency = (amount: number, currency: string) => {
        return new Intl.NumberFormat(i18n.language, {
            style: "currency",
            currency: currency
        }).format(amount);
    };

    const handleRedoTransaction = (transactionData: Omit<Transaction, "id" | "created_at"> & { account_id: number }) => {
        createTransaction(transactionData, {
            onSuccess: () => {
                setIsRedoModalOpen(false);
                navigate('/transactions');
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-screen">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
            </div>
        );
    }

    if (isError || !transaction) {
        return (
            <div className="flex flex-col items-center justify-center h-screen space-y-4">
                <p className="text-muted-foreground">{t('transactions.no_results')}</p>
                <button
                    onClick={() => navigate(-1)}
                    className="text-primary hover:underline"
                >
                    {t('common.retry')}
                </button>
            </div>
        );
    }

    const account = accounts?.find(a => a.id === transaction.account_id);
    const category = categories?.find(c => c.id === transaction.category_id);
    const currency = account?.currency || user?.currency || 'USD';

    return (
        <div className="min-h-screen bg-background flex flex-col pt-4">
            {/* Minimal Header */}
            <div className="px-4 sm:px-6 flex items-center justify-between mb-8">
                <button
                    onClick={() => navigate(-1)}
                    className="w-10 h-10 bg-card/50 backdrop-blur-md border border-border/50 flex items-center justify-center rounded-2xl shadow-sm"
                >
                    <ArrowLeft size={20} className="text-foreground" />
                </button>
                <div className="flex flex-col items-center">
                    <span className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/50">{t('transactions.title')}</span>
                    <h1 className="font-bold text-[13px] sm:text-sm tracking-tight">#{transaction.id}</h1>
                </div>
                <div className="w-10 h-10" /> {/* Spacer */}
            </div>

            <div className="px-4 sm:px-6 flex-1 max-w-lg mx-auto w-full space-y-10 pb-20">

                {/* Hero section with Amount */}
                <div className="flex flex-col items-center text-center space-y-6">
                    <div
                        className={cn(
                            "w-24 h-24 rounded-[3rem] flex items-center justify-center shadow-2xl skew-y-1 transition-transform border-4 border-background",
                            transaction.type === 'income' ? "bg-emerald-500 shadow-emerald-500/20" : "bg-red-500 shadow-red-500/20"
                        )}
                    >
                        {transaction.type === 'income' ? (
                            <TrendingUp size={40} className="text-white" strokeWidth={2.5} />
                        ) : (
                            <TrendingDown size={40} className="text-white" strokeWidth={2.5} />
                        )}
                    </div>

                    <div className="space-y-1">
                        <h2
                            className={cn(
                                "text-xl sm:text-2xl font-black tracking-tight",
                                transaction.type === 'income' ? "text-emerald-500" : "text-foreground"
                            )}
                        >
                            {formatCurrency(transaction.amount, currency)}
                            {transaction.type === 'income' ? ' +' : ' -'}
                        </h2>
                        <p className="text-base sm:text-lg font-bold tracking-tight text-muted-foreground">{transaction.description}</p>
                    </div>
                </div>

                {/* Details List - Minimalist approach */}
                <div className="space-y-4">
                    <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-muted-foreground/40 px-2">{t('common.details', 'Details')}</h3>

                    <div className="bg-card/30 backdrop-blur-xl border border-border/40 rounded-[2.5rem] overflow-hidden">
                        {/* Date & Time */}
                        <div className="flex items-center justify-between p-4 sm:p-6">
                            <div className="flex items-center space-x-3 sm:space-x-4">
                                <div className="w-10 h-10 rounded-2xl bg-muted/40 flex items-center justify-center text-muted-foreground shrink-0">
                                    <Calendar size={18} strokeWidth={2.5} />
                                </div>
                                <span className="text-[13px] font-bold text-muted-foreground/80">{t('transactions.date', 'Date')}</span>
                            </div>
                            <div className="text-right">
                                <p className="font-bold text-[13px]">
                                    {new Date(transaction.created_at).toLocaleDateString(i18n.language, {
                                        day: 'numeric',
                                        month: 'long',
                                        year: 'numeric'
                                    })}
                                </p>
                                <p className="text-[11px] font-black text-muted-foreground/40 uppercase tracking-widest mt-0.5">
                                    {new Date(transaction.created_at).toLocaleTimeString(i18n.language, {
                                        hour: '2-digit',
                                        minute: '2-digit'
                                    })}
                                </p>
                            </div>
                        </div>

                        <div className="h-px bg-border/20 mx-4 sm:mx-6" />

                        {/* Category Row */}
                        <div className="flex items-center justify-between p-4 sm:p-6">
                            <div className="flex items-center space-x-3 sm:space-x-4">
                                <div className="w-10 h-10 rounded-2xl bg-muted/40 flex items-center justify-center text-muted-foreground shrink-0">
                                    <Tag size={18} strokeWidth={2.5} />
                                </div>
                                <span className="text-[13px] font-bold text-muted-foreground/80">{t('transactions.category')}</span>
                            </div>
                            <div className="flex items-center bg-muted/30 px-3 py-1.5 rounded-xl border border-border/30 shadow-inner">
                                <span className="text-xs font-black uppercase tracking-wider">
                                    {category?.name || t('transactions.uncategorized')}
                                </span>
                            </div>
                        </div>

                        <div className="h-px bg-border/20 mx-4 sm:mx-6" />

                        {/* Type Row */}
                        <div className="flex items-center justify-between p-4 sm:p-6">
                            <div className="flex items-center space-x-3 sm:space-x-4">
                                <div className="w-10 h-10 rounded-2xl bg-muted/40 flex items-center justify-center text-muted-foreground shrink-0">
                                    <TrendingUp size={18} strokeWidth={2.5} />
                                </div>
                                <span className="text-[13px] font-bold text-muted-foreground/80">{t('transactions.type')}</span>
                            </div>
                            <div className={cn(
                                "px-3 py-1.5 rounded-xl border font-black uppercase tracking-wider text-[10px]",
                                transaction.type === 'income' ? "bg-emerald-500/10 border-emerald-500/20 text-emerald-600" : "bg-red-500/10 border-red-500/20 text-red-500"
                            )}>
                                {transaction.type === 'income' ? t('transactions.income') : t('transactions.expense')}
                            </div>
                        </div>

                        <div className="h-px bg-border/20 mx-4 sm:mx-6" />

                        {/* Account Row */}
                        <div className="flex items-center justify-between p-4 sm:p-6">
                            <div className="flex items-center space-x-3 sm:space-x-4">
                                <div className="w-10 h-10 rounded-2xl bg-muted/40 flex items-center justify-center text-muted-foreground shrink-0">
                                    <Wallet size={18} strokeWidth={2.5} />
                                </div>
                                <span className="text-[13px] font-bold text-muted-foreground/80">{t('settings.account')}</span>
                            </div>
                            <span className="text-[13px] font-black tracking-tight">{account?.name || 'ΓÇö'}</span>
                        </div>
                    </div>
                </div>

                {/* Actions */}
                <div className="space-y-3 pt-4">
                    <button
                        onClick={() => setIsRedoModalOpen(true)}
                        className="w-full bg-primary text-primary-foreground font-bold py-5 rounded-3xl flex items-center justify-center space-x-2 shadow-lg shadow-primary/25 active:scale-[0.98] transition-all"
                    >
                        <RefreshCcw size={18} strokeWidth={2.5} />
                        <span>{t('transactions.repeat_transaction', 'Repeat Transaction')}</span>
                    </button>

                    <button
                        onClick={async () => {
                            if (confirm("Delete this transaction?")) {
                                try {
                                    await api.delete(`/transactions/${transaction.id}`);
                                    navigate(-1);
                                } catch (e) {
                                    alert("Error deleting transaction");
                                }
                            }
                        }}
                        className="w-full bg-red-500/5 hover:bg-red-500/10 border border-red-500/20 text-red-500 font-black uppercase tracking-[0.2em] text-[11px] py-4 rounded-3xl transition-all"
                    >
                        {t('transactions.delete')}
                    </button>
                </div>
            </div>

            <AddTransactionModal
                isOpen={isRedoModalOpen}
                onClose={() => setIsRedoModalOpen(false)}
                onAdd={handleRedoTransaction}
                initialData={transaction}
            />
        </div>
    );
}

import { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuthStore } from "@/store/auth-store";
import { useTranslation } from "react-i18next";

import api from "@/lib/axios";
import { Lock, User, Eye, EyeOff, ArrowRight } from "lucide-react";

export default function Login() {
    const [error, setError] = useState("");
    const [isLoading, setIsLoading] = useState(false);
    const [showPassword, setShowPassword] = useState(false);
    const login = useAuthStore((state) => state.setAuth);
    const isAuthenticated = useAuthStore((state) => state.isAuthenticated);
    const { t } = useTranslation();
    const navigate = useNavigate();
    const [identifier, setIdentifier] = useState("");
    const [password, setPassword] = useState("");

    useEffect(() => {
        if (isAuthenticated) {
            navigate("/", { replace: true });
        }
    }, [isAuthenticated, navigate]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError("");
        setIsLoading(true);

        try {
            const { data } = await api.post("/auth/login", { identifier, password });
            login(data.user);
            navigate("/");
        } catch (err: any) {
            setError(err.response?.data?.error || "Failed to login");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center p-4 relative overflow-hidden">
            {/* Background Decoration */}
            <div className="fixed inset-0 pointer-events-none -z-10">
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full h-1/2 bg-primary/5 blur-[120px] rounded-full" />
            </div>

            <div className="w-full max-w-md space-y-8 bg-card/30 backdrop-blur-md p-8 rounded-[2.5rem] border border-white/5 shadow-2xl">
                <div className="text-center space-y-2">
                    <h1 className="text-3xl font-black tracking-tight">{t("auth.login_title")}</h1>
                    <p className="text-sm font-medium text-muted-foreground">{t("auth.login_subtitle")}</p>
                </div>

                <form onSubmit={handleSubmit} className="space-y-6">
                    {error && (
                        <div
                            className="bg-destructive/10 text-destructive text-xs p-3 rounded-2xl text-center font-bold border border-destructive/20"
                        >
                            {error}
                        </div>
                    )}

                    <div className="space-y-4">
                        <div className="relative group">
                            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground group-focus-within:text-primary transition-colors" size={20} />
                            <input
                                type="text"
                                placeholder={t("auth.email_or_username_placeholder")}
                                value={identifier}
                                onChange={(e) => setIdentifier(e.target.value)}
                                className="w-full bg-background/50 border border-border rounded-2xl py-3.5 pl-12 pr-4 focus:border-primary focus:bg-background outline-none transition-all font-medium placeholder:text-muted-foreground/50"
                                required
                            />
                        </div>

                        <div className="relative group">
                            <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground group-focus-within:text-primary transition-colors" size={20} />
                            <input
                                type={showPassword ? "text" : "password"}
                                placeholder={t("auth.password_placeholder")}
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full bg-background/50 border border-border rounded-2xl py-3.5 pl-12 pr-12 focus:border-primary focus:bg-background outline-none transition-all font-medium placeholder:text-muted-foreground/50"
                                required
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-primary transition-colors focus:outline-none"
                            >
                                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                            </button>
                        </div>
                    </div>

                    <button
                        type="submit"
                        disabled={isLoading}
                        className="w-full bg-primary text-primary-foreground font-bold py-3.5 rounded-2xl hover:opacity-90 hover:scale-[1.02] active:scale-[0.98] transition-all disabled:opacity-50 disabled:scale-100 flex items-center justify-center space-x-2 shadow-lg shadow-primary/25"
                    >
                        {isLoading ? (
                            <div className="w-5 h-5 border-2 border-primary-foreground/30 border-t-primary-foreground rounded-full animate-spin" />
                        ) : (
                            <>
                                <span>{t("auth.login_button")}</span>
                                <ArrowRight size={18} strokeWidth={2.5} />
                            </>
                        )}
                    </button>
                </form>

                <div className="text-center">
                    <p className="text-muted-foreground text-sm font-medium">
                        {t("auth.no_account")}{" "}
                        <Link to="/register" className="text-primary font-bold hover:underline transition-all">
                            {t("auth.register_button")}
                        </Link>
                    </p>
                </div>
            </div>
        </div>
    );
}

import { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuthStore } from "@/store/auth-store";
import { useTranslation } from "react-i18next";

import api from "@/lib/axios";
import { Lock, Mail, User, Eye, EyeOff, ArrowRight } from "lucide-react";

export default function Register() {
    const [error, setError] = useState("");
    const [isLoading, setIsLoading] = useState(false);
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const register = useAuthStore((state) => state.setAuth);
    const isAuthenticated = useAuthStore((state) => state.isAuthenticated);
    const { t } = useTranslation();
    const navigate = useNavigate();
    const [username, setUsername] = useState("");
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [confirmPassword, setConfirmPassword] = useState("");

    useEffect(() => {
        if (isAuthenticated) {
            navigate("/", { replace: true });
        }
    }, [isAuthenticated, navigate]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError("");

        if (password !== confirmPassword) {
            setError(t("auth.password_mismatch") || "Passwords do not match");
            return;
        }

        setIsLoading(true);

        try {
            const { data } = await api.post("/auth/register", { username, email, password });
            register(data.user);
            navigate("/");
        } catch (err: any) {
            setError(err.response?.data?.error || "Failed to register");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center p-4 relative overflow-hidden">
            {/* Background Decoration */}
            <div className="fixed inset-0 pointer-events-none -z-10">
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full h-1/2 bg-primary/5 blur-[120px] rounded-full" />
            </div>

            <div className="w-full max-w-md space-y-8 bg-card/30 backdrop-blur-md p-8 rounded-[2.5rem] border border-white/5 shadow-2xl">
                <div className="text-center space-y-2">
                    <h1 className="text-3xl font-black tracking-tight">{t("auth.register_title")}</h1>
                    <p className="text-sm font-medium text-muted-foreground">{t("auth.register_subtitle")}</p>
                </div>

                <form onSubmit={handleSubmit} className="space-y-5">
                    {error && (
                        <div
                            className="bg-destructive/10 text-destructive text-xs p-3 rounded-2xl text-center font-bold border border-destructive/20"
                        >
                            {error}
                        </div>
                    )}

                    <div className="space-y-4">
                        <div className="relative group">
                            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground group-focus-within:text-primary transition-colors" size={20} />
                            <input
                                type="text"
                                placeholder={t("auth.username_placeholder")}
                                value={username}
                                onChange={(e) => setUsername(e.target.value)}
                                className="w-full bg-background/50 border border-border rounded-2xl py-3.5 pl-12 pr-4 focus:border-primary focus:bg-background outline-none transition-all font-medium placeholder:text-muted-foreground/50"
                                required
                            />
                        </div>

                        <div className="relative group">
                            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground group-focus-within:text-primary transition-colors" size={20} />
                            <input
                                type="email"
                                placeholder={t("auth.email_placeholder")}
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                className="w-full bg-background/50 border border-border rounded-2xl py-3.5 pl-12 pr-4 focus:border-primary focus:bg-background outline-none transition-all font-medium placeholder:text-muted-foreground/50"
                                required
                            />
                        </div>

                        <div className="relative group">
                            <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground group-focus-within:text-primary transition-colors" size={20} />
                            <input
                                type={showPassword ? "text" : "password"}
                                placeholder={t("auth.password_placeholder")}
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full bg-background/50 border border-border rounded-2xl py-3.5 pl-12 pr-12 focus:border-primary focus:bg-background outline-none transition-all font-medium placeholder:text-muted-foreground/50"
                                required
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-primary transition-colors focus:outline-none"
                            >
                                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                            </button>
                        </div>

                        <div className="relative group">
                            <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground group-focus-within:text-primary transition-colors" size={20} />
                            <input
                                type={showConfirmPassword ? "text" : "password"}
                                placeholder={t("auth.confirm_password_placeholder") || "Confirm Password"}
                                value={confirmPassword}
                                onChange={(e) => setConfirmPassword(e.target.value)}
                                className="w-full bg-background/50 border border-border rounded-2xl py-3.5 pl-12 pr-12 focus:border-primary focus:bg-background outline-none transition-all font-medium placeholder:text-muted-foreground/50"
                                required
                            />
                            <button
                                type="button"
                                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                className="absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-primary transition-colors focus:outline-none"
                            >
                                {showConfirmPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                            </button>
                        </div>
                    </div>

                    <button
                        type="submit"
                        disabled={isLoading}
                        className="w-full bg-primary text-primary-foreground font-bold py-3.5 rounded-2xl hover:opacity-90 hover:scale-[1.02] active:scale-[0.98] transition-all disabled:opacity-50 disabled:scale-100 flex items-center justify-center space-x-2 shadow-lg shadow-primary/25"
                    >
                        {isLoading ? (
                            <div className="w-5 h-5 border-2 border-primary-foreground/30 border-t-primary-foreground rounded-full animate-spin" />
                        ) : (
                            <>
                                <span>{t("auth.register_button")}</span>
                                <ArrowRight size={18} strokeWidth={2.5} />
                            </>
                        )}
                    </button>
                </form>

                <div className="text-center">
                    <p className="text-muted-foreground text-sm font-medium">
                        {t("auth.have_account")}{" "}
                        <Link to="/login" className="text-primary font-bold hover:underline transition-all">
                            {t("auth.login_button")}
                        </Link>
                    </p>
                </div>
            </div>
        </div>
    );
}

import { useTranslation } from "react-i18next";
import { useChangePassword, useLoginHistory } from "@/hooks/use-api";
import { ArrowLeft, Lock, KeyRound, ShieldCheck, History, Laptop, Smartphone } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { useState } from "react";
import { cn } from "@/lib/utils";
import { formatDistanceToNow } from "date-fns";

export default function SecurityPrivacy() {
    const { t } = useTranslation();
    const navigate = useNavigate();
    const changePassword = useChangePassword();
    const { data: loginHistory } = useLoginHistory();

    // Password Form State
    const [oldPassword, setOldPassword] = useState("");
    const [newPassword, setNewPassword] = useState("");
    const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

    const handlePasswordChange = async (e: React.FormEvent) => {
        e.preventDefault();
        setMessage(null);

        if (newPassword.length < 8) {
            setMessage({ type: 'error', text: t('auth.password_min_length') || "Password must be at least 8 characters long" });
            return;
        }

        changePassword.mutate({ oldPassword, newPassword }, {
            onSuccess: () => {
                setMessage({ type: 'success', text: t('settings.password_changed') || "Password updated successfully" });
                setOldPassword("");
                setNewPassword("");
            },
            onError: (err: any) => {
                setMessage({ type: 'error', text: err.response?.data?.error || "Failed to update password" });
            }
        });
    };

    return (
        <div className="pb-24 space-y-8 max-w-2xl mx-auto px-4 sm:px-0">
            <div className="flex items-center space-x-4 pt-6 pb-2">
                <button
                    onClick={() => navigate(-1)}
                    className="p-2 rounded-xl bg-card border border-border hover:bg-muted transition-colors"
                >
                    <ArrowLeft size={20} />
                </button>
                <h1 className="text-2xl font-black tracking-tight">{t('settings.security_privacy') || "Security & Privacy"}</h1>
            </div>

            {/* Change Password Section */}
            <div className="space-y-4">
                <h3 className="text-xs uppercase tracking-[0.2em] font-black text-muted-foreground/60 px-2">
                    {t('settings.change_password') || "Change Password"}
                </h3>
                <div className="bg-card border border-border rounded-[2rem] p-6 shadow-xl shadow-primary/5">
                    <form onSubmit={handlePasswordChange} className="space-y-4">
                        <div className="space-y-2">
                            <label className="text-xs font-black uppercase tracking-widest text-muted-foreground ml-1">
                                {t('auth.current_password') || "Current Password"}
                            </label>
                            <div className="relative">
                                <Lock className="absolute left-4 top-3.5 text-muted-foreground/50" size={18} />
                                <input
                                    type="password"
                                    value={oldPassword}
                                    onChange={(e) => setOldPassword(e.target.value)}
                                    className="w-full bg-muted/30 border border-border rounded-xl py-3 pl-11 pr-4 font-medium focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none transition-all"
                                    placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                                    required
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-xs font-black uppercase tracking-widest text-muted-foreground ml-1">
                                {t('auth.new_password') || "New Password"}
                            </label>
                            <div className="relative">
                                <KeyRound className="absolute left-4 top-3.5 text-muted-foreground/50" size={18} />
                                <input
                                    type="password"
                                    value={newPassword}
                                    onChange={(e) => setNewPassword(e.target.value)}
                                    className="w-full bg-muted/30 border border-border rounded-xl py-3 pl-11 pr-4 font-medium focus:ring-2 focus:ring-primary/20 focus:border-primary outline-none transition-all"
                                    placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                                    required
                                />
                            </div>
                        </div>

                        {message && (
                            <div className={cn(
                                "p-3 rounded-xl text-sm font-bold text-center animate-in fade-in slide-in-from-top-1",
                                message.type === 'success' ? "bg-green-500/10 text-green-600" : "bg-red-500/10 text-red-600"
                            )}>
                                {message.text}
                            </div>
                        )}

                        <button
                            type="submit"
                            disabled={changePassword.isPending}
                            className={cn(
                                "w-full py-3.5 rounded-xl font-black tracking-tight text-white shadow-lg transition-all active:scale-[0.98]",
                                changePassword.isPending ? "bg-muted text-muted-foreground cursor-not-allowed" : "bg-gradient-to-r from-amber-500 to-orange-500 hover:shadow-orange-500/25"
                            )}
                        >
                            {changePassword.isPending ? "Updating..." : (t('settings.update_password') || "Update Password")}
                        </button>
                    </form>
                </div>
            </div>

            {/* Login History Section */}
            <div className="space-y-4">
                <h3 className="text-xs uppercase tracking-[0.2em] font-black text-muted-foreground/60 px-2 flex items-center justify-between">
                    <span>{t('settings.login_history') || "Login History"}</span>
                    <ShieldCheck size={14} className="text-muted-foreground" />
                </h3>
                <div className="bg-card border border-border rounded-[2rem] overflow-hidden shadow-xl shadow-primary/5">
                    {loginHistory?.length === 0 ? (
                        <div className="p-8 text-center text-muted-foreground text-sm">
                            No login history available.
                        </div>
                    ) : (
                        <div className="divide-y divide-border/30">
                            {loginHistory?.map((login: any) => (
                                <div key={login.id} className="p-4 hover:bg-muted/30 transition-colors flex items-center justify-between">
                                    <div className="flex items-center space-x-3">
                                        <div className={cn(
                                            "p-2.5 rounded-xl",
                                            login.deviceType === 'mobile' ? "bg-blue-500/10 text-blue-500" : "bg-slate-500/10 text-slate-500"
                                        )}>
                                            {login.deviceType === 'mobile' ? <Smartphone size={18} /> : <Laptop size={18} />}
                                        </div>
                                        <div>
                                            <p className="font-bold text-sm tracking-tight">
                                                {login.ipAddress || "Unknown IP"}
                                            </p>
                                            <p className="text-[10px] text-muted-foreground uppercase tracking-wider font-semibold">
                                                {login.userAgent && login.userAgent.length > 30
                                                    ? login.userAgent.substring(0, 30) + "..."
                                                    : login.userAgent || "Unknown Device"}
                                            </p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <div className={cn(
                                            "inline-flex items-center px-2 py-0.5 rounded-md text-[10px] font-black uppercase tracking-wider mb-1",
                                            login.success ? "bg-green-500/10 text-green-600" : "bg-red-500/10 text-red-600"
                                        )}>
                                            {login.success ? "Success" : "Failed"}
                                        </div>
                                        <p className="text-[10px] text-muted-foreground font-medium flex items-center justify-end gap-1">
                                            <History size={10} />
                                            {formatDistanceToNow(new Date(login.timestamp), { addSuffix: true })}
                                        </p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
                <p className="text-[10px] text-muted-foreground text-center px-4">
                    {t('settings.security_notice') || "If you see suspicious activity, change your password immediately."}
                </p>
            </div>
        </div>
    );
}

// Mock for virtual:pwa-register/react
export function useRegisterSW(options?: any) {
    return {
        needRefresh: [false, (value: boolean) => { }],
        offlineReady: [false, (value: boolean) => { }],
        updateServiceWorker: (reloadPage?: boolean) => { },
    };
